// Yale Bright Star Catalogue (BSC5), public domain. Positions are J2000.
const DATA = ' '.trim();
export const STAR_MAP_WIDTH = 4096;
export const STAR_MAP_HEIGHT = 2048;
const COLOURS = [[155,190,255],[175,205,255],[205,220,255],[245,245,255],[255,244,220],[255,210,165],[255,175,120]];

export function createStarMapData() {
  const raw = Uint8Array.from(atob(DATA), (c) => c.charCodeAt(0));
  const pixels = new Uint8Array(STAR_MAP_WIDTH * STAR_MAP_HEIGHT * 4);
  for (let i = 0; i < raw.length; i += 7) {
    const ra = raw[i] | raw[i + 1] << 8;
    const dec = raw[i + 2] | raw[i + 3] << 8;
    const mag = (raw[i + 4] | raw[i + 5] << 8) / 100 - 2;
    const x = Math.min(STAR_MAP_WIDTH - 1, Math.round(ra / 65535 * (STAR_MAP_WIDTH - 1)));
    const y = Math.min(STAR_MAP_HEIGHT - 1, Math.round((1 - dec / 65535) * (STAR_MAP_HEIGHT - 1)));
    const colour = COLOURS[Math.min(6, raw[i + 6])] || COLOURS[3];
    const peak = Math.min(255, Math.round(255 * Math.pow(2.512, -0.34 * (mag - 1))));
    const radius = mag < 0.5 ? 3 : mag < 2 ? 2 : 1;
    for (let dy = -radius; dy <= radius; dy++) for (let dx = -radius; dx <= radius; dx++) {
      const xx = (x + dx + STAR_MAP_WIDTH) % STAR_MAP_WIDTH, yy = y + dy;
      if (yy < 0 || yy >= STAR_MAP_HEIGHT) continue;
      const falloff = Math.exp(-(dx * dx + dy * dy) / Math.max(0.7, radius * 0.65));
      const o = (yy * STAR_MAP_WIDTH + xx) * 4;
      for (let c = 0; c < 3; c++) pixels[o + c] = Math.min(255, pixels[o + c] + Math.round(colour[c] * peak / 255 * falloff));
      pixels[o + 3] = 255;
    }
  }
  return pixels;
}
